  const desktopRef = useRef<HTMLDivElement>(null); const gestureRef = useRef<{ y: number; touch: boolean } | null>(null); const nativeFullscreenRef = useRef(false); const stateRef = useRef(state); const lastFarmReadyRef = useRef(0); const [viewportSize, setViewportSize] = useState({ width: globalThis.window.innerWidth, height: globalThis.window.innerHeight });
