  useEffect(() => { unlockLabAchievement('MODERN_OS_USER'); const timer = window.setInterval(() => setClock(new Date()), 30_000); const boot = window.setTimeout(() => { setBooting(false); setState((current) => ({ ...current, booted: true })); }, reducedMotion ? 100 : 1250); return () => { clearInterval(timer); clearTimeout(boot); }; }, [reducedMotion]);
  useEffect(() => { if (state.windows.length >= 3) unlockLabAchievement('MODERN_MULTITASKER'); }, [state.windows.length]);
  useEffect(() => { const update = () => { const element = desktopRef.current; const next = { width: element?.clientWidth || globalThis.window.innerWidth, height: element?.clientHeight || globalThis.window.innerHeight }; setViewportSize((current) => current.width === next.width && current.height === next.height ? current : next); }; update(); globalThis.window.addEventListener('resize', update); const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(update); if (desktopRef.current) observer?.observe(desktopRef.current); return () => { globalThis.window.removeEventListener('resize', update); observer?.disconnect(); }; }, []);
  const openApp = useCallback((id: ModernAppId) => { updateState(setState, (current) => openModernWindow(current, id, appById[id].label)); setSearch(false); setOverview(false); if (id === 'network') unlockLabAchievement('MODERN_EXPLORER'); }, []);
