  if (poweredOff) return <LabShell experimentId="modern-os" title="SITEVL NOVA" description="Современная виртуальная desktop-система SITEVL." canonicalPath="/lab/modern-os" status="ИНТЕРАКТИВНО · MODERN OS" immersive className="nova-host"><div className="nova-power-off"><div className="nova-glyph">N</div><strong>Система выключена</strong><button type="button" onClick={() => { setPoweredOff(false); setBooting(true); window.setTimeout(() => setBooting(false), 900); }}><Power />Включить SITEVL NOVA</button></div></LabShell>;
